const TIMEZONE_SET = new Set(TIMEZONE_ENTRIES.map(entry => entry.tz));

/** True when the identifier is one of the known country reference zones. */
export function isKnownTimezone(tz: string | null | undefined): boolean {
  return !!tz && TIMEZONE_SET.has(tz);
}

/** The browser's own IANA zone, or "UTC" when it cannot be resolved. */
export function detectLocalTimezone(): string {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  } catch {
    return "UTC";
  }
}

/**
 * Short UTC offset label for a zone at a given instant, e.g. "UTC+1",
 * "UTC-5", "UTC+5:30", or "UTC" for zero. Daylight saving is applied by the
 * Intl data for the requested instant.
 */
export function timezoneOffsetLabel(tz: string, at: Date = new Date()): string {
  try {
    const parts = new Intl.DateTimeFormat("en-US", { timeZone: tz, timeZoneName: "shortOffset" }).formatToParts(at);
    const raw = parts.find(part => part.type === "timeZoneName")?.value || "GMT";
    if (/^(GMT|UTC)$/.test(raw)) return "UTC±0";
    return raw.replace(/^GMT/, "UTC").replace("UTC+0", "UTC±0");
  } catch {
    return "UTC";
  }
}

/**
 * Wall-clock time in a zone, e.g. "14:32" or "14:32:07". Uses a 24-hour clock
 * so the value never depends on the viewer's locale preferences.
 */
export function formatTimezoneClock(tz: string, at: Date = new Date(), withSeconds = false): string {
  try {
    return new Intl.DateTimeFormat("en-GB", {
      timeZone: tz,
      hour: "2-digit",
      minute: "2-digit",
      ...(withSeconds ? { second: "2-digit" } : {}),
      hour12: false,
    }).format(at);
  } catch {
    return "--:--";
  }
}

/** The human-readable label of a zone's city, e.g. "America/New_York" -> "New York". */
export function timezoneCityLabel(tz: string): string {
  const city = String(tz || "").split("/").pop() || tz;
  return city.replace(/_/g, " ");
}
